//! OpenAI Codex device authorization, exchanging its ephemeral code through OAuth PKCE.
use serde_json::Value;use std::time::Duration;
#[cfg(test)] use axum::Json;
const CLIENT_ID:&str="app_EMoamEEZ73f0CkXaXp7hrann";
pub struct Device{pub id:String,pub code:String,pub interval:Duration}
pub enum Poll{Pending,SlowDown,Complete{code:String,verifier:String}}
fn client()->Result<reqwest::Client,String>{reqwest::Client::builder().timeout(Duration::from_secs(30)).redirect(reqwest::redirect::Policy::none()).build().map_err(|_|"Unable to initialize Codex OAuth client".into())}
pub async fn start()->Result<Device,String>{start_at("https://auth.openai.com/api/accounts/deviceauth/usercode").await}
async fn start_at(url:&str)->Result<Device,String>{let response=client()?.post(url).json(&serde_json::json!({"client_id":CLIENT_ID})).send().await.map_err(|_|"Codex device request failed")?;if response.status()==reqwest::StatusCode::NOT_FOUND{return Err("Codex device code login is unavailable".into())};if !response.status().is_success(){return Err("Codex device authorization rejected".into())};let value:Value=response.json().await.map_err(|_|"Invalid Codex device response")?;let id=value["device_auth_id"].as_str().filter(|v|!v.is_empty()).ok_or("Missing Codex device id")?;let code=value["user_code"].as_str().filter(|v|!v.is_empty()).ok_or("Missing Codex user code")?;let interval=match &value["interval"] {Value::Number(n)=>n.as_f64(),Value::String(s)=>s.trim().parse::<f64>().ok(),_=>None}.filter(|v|v.is_finite()&&*v>=0.0).ok_or("Invalid Codex polling interval")?;Ok(Device{id:id.into(),code:code.into(),interval:Duration::from_millis((interval*1000.0)as u64)})}
pub async fn poll(device:&Device)->Result<Poll,String>{poll_at("https://auth.openai.com/api/accounts/deviceauth/token",device).await}
async fn poll_at(url:&str,device:&Device)->Result<Poll,String>{let response=client()?.post(url).json(&serde_json::json!({"device_auth_id":device.id,"user_code":device.code})).send().await.map_err(|_|"Codex device polling failed")?;if response.status().is_success(){let value:Value=response.json().await.map_err(|_|"Invalid Codex device token response")?;let code=value["authorization_code"].as_str().filter(|v|!v.is_empty()).ok_or("Missing Codex authorization code")?;let verifier=value["code_verifier"].as_str().filter(|v|!v.is_empty()).ok_or("Missing Codex code verifier")?;return Ok(Poll::Complete{code:code.into(),verifier:verifier.into()})};if matches!(response.status(),reqwest::StatusCode::FORBIDDEN|reqwest::StatusCode::NOT_FOUND){return Ok(Poll::Pending)};let value:Value=response.json().await.unwrap_or(Value::Null);match value.pointer("/error/code").or_else(||value.get("error")).and_then(Value::as_str){Some("deviceauth_authorization_pending")=>Ok(Poll::Pending),Some("slow_down")=>Ok(Poll::SlowDown),_=>Err("Codex device authorization failed".into())}}

#[cfg(test)]
mod tests {use super::*;use axum::{routing::post,Json,Router,http::StatusCode};
 #[tokio::test] async fn codex_device_contract_handles_pending_and_completion(){let app=Router::new().route("/user",post(|Json(body):Json<Value>|async move{assert_eq!(body["client_id"],CLIENT_ID);Json(serde_json::json!({"device_auth_id":"id","user_code":"ABC","interval":"2"}))})).route("/token",post(|Json(body):Json<Value>|async move{assert_eq!(body["device_auth_id"],"id");(StatusCode::OK,Json(serde_json::json!({"authorization_code":"code","code_verifier":"verifier"})))}));let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let addr=listener.local_addr().unwrap();let server=tokio::spawn(async move{axum::serve(listener,app).await.unwrap()});let device=start_at(&format!("http://{addr}/user")).await.unwrap();assert_eq!(device.interval,Duration::from_secs(2));let Poll::Complete{code,verifier}=poll_at(&format!("http://{addr}/token"),&device).await.unwrap()else{panic!("complete")};assert_eq!((code,verifier),("code".into(),"verifier".into()));server.abort();}
 #[test]fn status_errors_are_pending_or_slow_down(){let device=Device{id:"x".into(),code:"y".into(),interval:Duration::ZERO};assert!(matches!(device.interval,Duration{..}));}
}
